  fr: { reflexTrainingDrill: { title: "Test de réflexe en ligne : cibles multiples", subtitle: "Rafale de cibles · Attention divisée", caption: "Éliminez plusieurs cibles avant leur disparition et gardez votre précision quand elles apparaissent ensemble.", rotate: "Passez en mode paysage pour élargir le champ de cibles.", score: "Score", time: "Temps", timeLeft: "Temps restant", level: "Niveau", bestScore: "Meilleur score", getReady: "PRÉPAREZ-VOUS", accuracy: "Précision", avgReaction: "Réaction moyenne", peakLevel: "Niveau maximal", maxCombo: "Combo maximal", missFlash: "Activer le flash d'erreur", sound: "Activer le son", rules: "Instructions et système de score", about: "À propos du test de réflexes à cibles multiples", aboutHeading: "Qu'est-ce que l'entraînement réflexe en rafale ?", aboutP1: "L'exercice affiche plusieurs cibles dans le même champ visuel et demande de les repérer, prioriser puis cliquer avant leur disparition. Contrairement à un signal unique prévisible, chaque rafale demande un choix de cible et une attention divisée.", aboutP2: "Le score n'est pas une mesure clinique des réflexes : c'est le résultat de la tâche avec votre matériel. Fréquence d'écran, images, navigateur, entrée, taille et durée des cibles, décisions visuelles et motrices interviennent.", audience: "À qui s'adresse cet exercice ?", audienceText: "Aux joueurs, compétiteurs esport et sportifs qui veulent travailler recherche de cibles multiples, priorisation et clics séquentiels précis.", attention: "Contrôle de l'attention divisée", attentionText: "Gardez plusieurs cibles dans le champ visuel et choisissez celle qui va bientôt disparaître ou qui peut être traitée sans risque.", interception: "Vitesse d'interception", interceptionText: "Construisez une séquence de clics rapide sans sacrifier la précision ni oublier les cibles restantes.", shareTitle: "Test de Réflexes : Cibles Multiples — mon score", shareText: "J'ai obtenu {score} points au test de réflexes à cibles multiples. Pouvez-vous faire mieux ?", ruleItems: [{ title: "Éliminer la rafale", detail: "+100 pts", badge: "Combo × niveau (+2 s, max. 60 s)", penaltyDetail: "+100 pts", penaltyBadge: "Combo × niveau (+2 s, max. 60 s)" }, { title: "Combo et rythme", detail: "Jusqu'à 3,0×", badge: "Cibles plus petites et plus brèves", penaltyDetail: "Jusqu'à 3,0×", penaltyBadge: "Cibles plus petites et plus brèves" }, { title: "Progression de niveau", detail: "Échelle continue", badge: "Plus de cibles simultanées, cibles réduites", penaltyDetail: "Échelle continue", penaltyBadge: "Plus de cibles simultanées, cibles réduites" }, { title: "Erreur et délai", detail: "−1 s", badge: "Combo réinitialisé", penaltyDetail: "−1 s", penaltyBadge: "Combo réinitialisé" }] } }
